/* Fully offline personalized staff-reading trainer. */
(()=>{
'use strict';
const C=PianoCore,GLYPHS=__GLYPHS__,$=id=>document.getElementById(id),MODE_TITLES=C.MODES;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='staff-keyboard-trainer-v2',STRATEGIES={adaptive:'自动加练',balanced:'均衡练习',custom:'自己选音',weak:'薄弱音专项'};
let db={version:5,study:StudyCore.defaults(),settings:{...C.DEFAULT},profiles:{},mistakes:[],reports:[],sound:true,fullKeyboard:false};
let storageFailed=false,session=null,q=null,page='practice',modalCallback=null,modalCleanup=null,modalRestoreFocus=null,lastReport=null,frame=0;
function validSettings(s){const mode=Object.hasOwn(C.MODES,s?.mode)?s.mode:'mixed';return {...C.DEFAULT,mode,difficulty:Object.hasOwn(C.RANGES,s?.difficulty)?s.difficulty:'beginner',noteCount:Number.isInteger(s?.noteCount)&&s.noteCount>=1&&s.noteCount<=15?Math.max(mode==='dual'?2:1,s.noteCount):mode==='dual'?2:1,strategy:Object.hasOwn(STRATEGIES,s?.strategy)?s.strategy:'adaptive',selectedNotes:[...new Set((Array.isArray(s?.selectedNotes)?s.selectedNotes:[]).filter(k=>typeof k==='string'&&/^(treble|bass):[A-G][2-6]$/.test(k)))].slice(0,80),timing:['auto','unlimited','custom'].includes(s?.timing)?s.timing:s?.limit===0?'unlimited':s?.limit?'custom':'auto',secondsPerNote:[3,5,8,10,15].includes(s?.secondsPerNote)?s.secondsPerNote:10,limit:Number.isInteger(s?.limit)&&s.limit>=3&&s.limit<=900?s.limit:10,count:[10,20,30].includes(s?.count)?s.count:20};}
function isTarget(t){return t&&['treble','bass'].includes(t.clef)&&Number.isInteger(t.note?.index)&&t.note.index>=14&&t.note.index<=49&&C.fromIndex(t.note.index).midi===t.note.midi;}
function normalize(x){if(![2,3,4,5].includes(x?.version))throw Error('格式不兼容');const out={version:5,study:StudyCore.normalize(x.study),settings:validSettings(x.settings),sound:x.sound!==false,fullKeyboard:x.fullKeyboard===true,profiles:{},mistakes:[],reports:[]};out.mistakes=(Array.isArray(x.mistakes)?x.mistakes:[]).filter(m=>typeof m.id==='string'&&Array.isArray(m.targets)&&m.targets.length>=1&&m.targets.length<=15&&m.targets.every(isTarget)&&Number.isInteger(m.errors)&&m.errors>0).slice(-200);out.reports=(Array.isArray(x.reports)?x.reports:[]).filter(r=>r&&typeof r.id==='string'&&Array.isArray(r.records)&&r.records.length<=30&&r.records.every(a=>Array.isArray(a.targets)&&a.targets.length<=15&&a.targets.every(isTarget)&&(r.version!==3||Array.isArray(a.slots)&&a.slots.length===a.targets.length))&&r.per?.treble&&r.per?.bass&&r.statuses).slice(-30);
 if(x.version>=3&&x.profiles&&typeof x.profiles==='object')Object.values(x.profiles).slice(0,100).forEach(p=>{if(!isTarget(p?.target)||!Array.isArray(p.samples))return;const samples=p.samples.filter(s=>typeof s.firstCorrect==='boolean'&&(s.firstMs===null||Number.isFinite(s.firstMs)&&s.firstMs>=0)&&(s.completionMs==null||Number.isFinite(s.completionMs)&&s.completionMs>=0)).slice(-20).map(s=>({...s,context:typeof s.context==='string'&&s.context.length<80?s.context:null}));const target={clef:p.target.clef,note:C.fromIndex(p.target.note.index)},seen=Math.max(samples.length,Number.isInteger(p.seen)?p.seen:0);out.profiles[C.profileKey(target)]={target,samples,seen,errors:Math.max(0,Math.min(seen,Number.isInteger(p.errors)?p.errors:0)),last:p.last};});
 out.reports.forEach(r=>r.records.forEach(a=>a.targets=a.targets.map(t=>({...t,note:C.fromIndex(t.note.index)}))));out.mistakes.forEach(m=>m.targets=m.targets.map(t=>({...t,note:C.fromIndex(t.note.index)})));if(x.version===2){out.reports.forEach(r=>r.records.forEach(a=>{if(a.targets.length===1)C.observe(out.profiles,a.targets[0],{reached:true,firstCorrect:!!a.firstMatch[0],firstMs:a.firstMatch[0]?a.firstMs:null,completed:['firstCorrect','corrected'].includes(a.status),paused:!!a.paused,date:r.date});}));out.mistakes.filter(m=>m.targets.length===1&&!out.profiles[C.profileKey(m.targets[0])]).forEach(m=>{for(let i=0;i<Math.min(m.errors,3);i++)C.observe(out.profiles,m.targets[0],{reached:true,firstCorrect:false,firstMs:null,date:m.last});});}
 out.mistakes.forEach(m=>m.targets=m.targets.map(t=>({...t,note:C.fromIndex(t.note.index)})));out.reports.forEach(r=>r.records.forEach(a=>a.targets=a.targets.map(t=>({...t,note:C.fromIndex(t.note.index)}))));return out;}
function load(){try{const raw=window.PianoAndroid?.loadData?.()||localStorage.getItem(STORAGE);if(!raw)return;const x=JSON.parse(raw);db=normalize(x);if(x.version===2){localStorage.setItem(STORAGE+'_backup_v2',raw);save();}}catch(e){showStorage('原有数据未能加载，原始内容未删除。你仍可正常练习。');}}
function showStorage(t){$('storageNotice').hidden=false;$('storageNotice').textContent=t;document.querySelector('.app-shell').classList.add('has-notice');}
function save(){try{const json=JSON.stringify(db);localStorage.setItem(STORAGE,json);window.PianoAndroid?.saveData?.(json);}catch(e){if(!storageFailed)showStorage('浏览器未能保存数据，请使用「薄弱音 → 导出数据」备份；本次仍可练习。');storageFailed=true;}}
function showSettingsError(t){$('settingsError').textContent=t;$('settingsError').hidden=!t;if(t){openDrawer();}}
function settingsFromUI(){const n=Number($('noteCount').value),limit=Number($('customLimit').value);if(!Number.isInteger(n)||n<1||n>15){showSettingsError('每题音符数须为1～15的整数。');return null;}if(db.settings.mode==='dual'&&n<2){showSettingsError('双谱表至少2个音，总数包含上下两谱表。');return null;}if($('timing').value==='custom'&&(!Number.isInteger(limit)||limit<3||limit>900)){showSettingsError('整题时限须为3～900的整数秒。');return null;}showSettingsError('');return validSettings({...db.settings,noteCount:n,strategy:$('strategy').value,difficulty:$('difficulty').value,timing:$('timing').value,secondsPerNote:Number($('secondsPerNote').value),limit,count:Number($('count').value)});}
function applySettings(){document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===db.settings.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===db.settings.mode));});for(const id of ['difficulty','noteCount','strategy','timing','secondsPerNote','count'])$(id).value=db.settings[id];$('customLimit').value=db.settings.limit;settingHints();}
function settingHints(){strategyHints();$('secondsPerNote').hidden=$('timing').value!=='auto';$('customLimit').hidden=$('timing').value!=='custom';$('noteCount').min=db.settings.mode==='dual'?2:1;$('noteHint').textContent=db.settings.mode==='dual'?'2～15个音，上下谱表合计，按编号作答。':'1～15个音，按编号依次作答。';const n=Number($('noteCount').value);$('limitHint').textContent=$('timing').value==='auto'?`整题 ${n} × ${$('secondsPerNote').value} = ${n*Number($('secondsPerNote').value)} 秒`:$('timing').value==='custom'?'所有音共享这个时限，不逐音重置。':'先认准，暂不限制时间。';}
function lockSettings(v){$('launch').hidden=v;['noteMinus','notePlus'].forEach(id=>$(id).disabled=v);document.querySelectorAll('.sidebar select,.sidebar input,[data-mode]').forEach(b=>b.disabled=v);$('start').disabled=v;$('chooseNotes').disabled=v;$('lockHint').hidden=!v;}
function updateSettings(){if(session?.active)return;settingHints();const s=settingsFromUI();if(!s)return;db.settings=s;save();renderPreview();updateHeader();if(page==='notePicker')renderNotePicker();}
function strategyHints(){
 const strategy=$('strategy').value,settings={...db.settings,strategy,difficulty:$('difficulty').value};
 $('chooseNotes').hidden=strategy!=='custom';
 const resolved=C.practicePool(settings,db.profiles),cs=C.clefsFor(settings.mode),counts=cs.map(c=>`${c==='treble'?'高音':'低音'} ${resolved.notes[c].length} 个`).join(' · ');
 $('strategyHint').textContent=strategy==='custom'?`当前可练：${counts}。仅从勾选的音中出题。`:strategy==='weak'?`当前薄弱音：${counts}。本轮只练这些音。`:strategy==='adaptive'?'易错音和慢音加练，同时覆盖其他音。':'依次覆盖当前音域，保持练习均衡。';
}
function validatePractice(settings){
 const resolved=C.practicePool(settings,db.profiles);
 if(!resolved.missing.length)return true;
 const clefs=resolved.missing.map(c=>c==='treble'?'高音':'低音').join('、');
 showSettingsError(settings.strategy==='custom'?`${clefs}谱表还没有选中的可练音。请点「选择练习音」，或调整模式／音域。`:`当前音域的${clefs}谱表没有薄弱音。可先练一轮自动加练，或调整模式／音域。`);
 return false;
}
function minimumDifficulty(targets){return ['beginner','basic','extended'].find(d=>targets.every(t=>C.pool(d,t.clef).some(n=>n.index===t.note.index)))||'extended';}
function modeForTargets(targets){const cs=new Set(targets.map(t=>t.clef));return cs.size===1?[...cs][0]:db.settings.mode==='dual'?'dual':'mixed';}
function configureSelected(keys){
 if(session?.active)return;
 const targets=keys.map(k=>{const [clef,pitch]=k.split(':');return{clef,note:C.parse(pitch)};});
 db.settings=validSettings({...db.settings,selectedNotes:keys,strategy:'custom',mode:modeForTargets(targets),difficulty:minimumDifficulty(targets)});
 save();applySettings();showSettingsError('');setPage('practice');openDrawer();
}
function configureWeak(targets){
 if(session?.active||!targets.length)return;
 db.settings=validSettings({...db.settings,strategy:'weak',mode:modeForTargets(targets),difficulty:minimumDifficulty(targets)});
 save();applySettings();showSettingsError('');setPage('practice');openDrawer();
}
function miniNote(target){
 const space=12,bottom=100,d=target.note.index-C.parse(target.clef==='treble'?'E4':'G2').index,y=bottom-d*space/2,x=122;
 let svg='<svg viewBox="0 0 190 160" aria-hidden="true">';
 for(let i=0;i<5;i++)svg+=`<line x1="12" x2="178" y1="${bottom-i*space}" y2="${bottom-i*space}" stroke="#83978c" stroke-width="1"/>`;
 svg+=`<path d="${GLYPHS[target.clef].path}" transform="translate(20 ${bottom-(target.clef==='treble'?space:space*3)}) scale(.048 -.048)" fill="#22352f"/>`;
 C.ledgerOffsets(d).forEach(k=>svg+=`<line x1="${x-15}" x2="${x+15}" y1="${bottom-k*space/2}" y2="${bottom-k*space/2}" stroke="#22352f" stroke-width="1.3"/>`);
 svg+=`<ellipse cx="${x}" cy="${y}" rx="8" ry="5.5" transform="rotate(-20 ${x} ${y})" fill="#27675f"/><line x1="${x+(d>=4?-7:7)}" x2="${x+(d>=4?-7:7)}" y1="${y}" y2="${y+(d>=4?42:-42)}" stroke="#27675f" stroke-width="1.8"/>`;
 return svg+'</svg>';
}
function renderNotePicker(){
 const cs=C.clefsFor(db.settings.mode),selected=new Set(db.settings.selectedNotes),visible=cs.flatMap(c=>C.pool(db.settings.difficulty,c).map(note=>({clef:c,note}))),counts=cs.map(c=>`${c==='treble'?'高音':'低音'} ${visible.filter(t=>t.clef===c&&selected.has(C.profileKey(t))).length} 个`).join(' · ');
 $('notePicker').innerHTML=`<div class="page-head"><div><h2>选择要练的音</h2><p>${esc(MODE_TITLES[db.settings.mode])} · ${$('difficulty').selectedOptions[0].textContent} · 中央C = C4</p></div><button id="pickerDone" class="primary">完成选音</button></div><div class="picker-toolbar"><strong>当前已选：${counts}</strong><div class="actions"><button id="selectAllNotes">全选当前音域</button><button id="clearVisibleNotes">清空当前音域</button></div></div><p class="helptext muted picker-help">按音符卡片勾选。切换模式或难度会保留原选择，出题只使用当前音域内的音。混合或双谱表需两种谱表各至少选一个音。</p>${cs.map(c=>`<section class="picker-section"><h3>${c==='treble'?'高音谱表 · 右手读谱':'低音谱表 · 左手读谱'}</h3><div class="note-grid">${visible.filter(t=>t.clef===c).map(t=>{const key=C.profileKey(t),chosen=selected.has(key),w=C.weakness(db.profiles[key],C.baseline(db.profiles,c));return `<label class="note-card ${chosen?'chosen':''}"><input type="checkbox" data-pick-note="${key}" ${chosen?'checked':''}><span class="note-card-title">${C.short(t.note)} <small>${C.SOLFEGE[t.note.letter]}</small></span>${miniNote(t)}<span class="note-card-caption">${w.error?'易错':w.slow?'较慢':t.note.midi===60?'中央C':C.location(c,t.note).replace(c==='treble'?'高音谱表':'低音谱表','')}</span></label>`;}).join('')}</div></section>`).join('')}<div class="picker-footer"><p class="helptext muted">同一谱表只选一个音时，这个音可以重复出现；多选时尽量避免连续重复。已选音符不会直接显示在作答提示中。</p><button id="pickerStart" class="primary">用这些音开始练习</button></div>`;
 $('notePicker').querySelectorAll('[data-pick-note]').forEach(input=>input.onchange=()=>{const keys=new Set(db.settings.selectedNotes);input.checked?keys.add(input.dataset.pickNote):keys.delete(input.dataset.pickNote);db.settings.selectedNotes=[...keys];save();strategyHints();showSettingsError('');renderNotePicker();$('notePicker').querySelector(`[data-pick-note="${input.dataset.pickNote}"]`)?.focus({preventScroll:true});});
 $('selectAllNotes').onclick=()=>{db.settings.selectedNotes=[...new Set([...db.settings.selectedNotes,...visible.map(C.profileKey)])];save();strategyHints();showSettingsError('');renderNotePicker();};
 $('clearVisibleNotes').onclick=()=>{const keys=new Set(visible.map(C.profileKey));db.settings.selectedNotes=db.settings.selectedNotes.filter(k=>!keys.has(k));save();strategyHints();showSettingsError('');renderNotePicker();};
 $('pickerDone').onclick=()=>{if(validatePractice(db.settings)){showSettingsError('');setPage('practice');if(innerWidth<=760){openDrawer();window.scrollTo(0,0);}}};
 $('pickerStart').onclick=()=>startRound();
}

function score(targets,active=-1){
 if(window.PianoTabletNotation)return PianoTabletNotation.classic(targets,active,q?.nextTarget||0);
 const dual=new Set(targets.map(t=>t.clef)).size>1,wide=(session?.active?session.settings:db.settings).difficulty==='extended',upper=wide?130:110,lower=wide?320:265,columns=innerWidth<=760?(dual?2:3):(dual?3:5),groups=dual?Math.ceil(targets.length/2):targets.length,rows=Math.ceil(groups/columns);let html='';
 for(let r=0;r<rows;r++){
  const inds=targets.map((t,i)=>i).filter(i=>Math.floor((dual?Math.floor(i/2):i)/columns)===r),height=dual?(wide?395:330):225;
  let svg=`<div class="score-row" data-score-row="${r}"><svg viewBox="0 ${dual?-12:0} 1100 ${height+(dual?12:0)}" role="img" aria-label="${dual?'双谱表':'五线谱'}，按编号依次作答">`;
  const clefs=dual?['treble','bass']:[targets[0].clef];
  clefs.forEach(c=>{const bottom=dual?(c==='treble'?upper:lower):145;for(let k=0;k<5;k++)svg+=`<line x1="95" x2="1060" y1="${bottom-k*18}" y2="${bottom-k*18}" stroke="#53685c" stroke-width="1.1"/>`;svg+=`<path d="${GLYPHS[c].path}" transform="translate(112 ${bottom-(c==='treble'?18:54)}) scale(.072 -.072)" fill="#22352f"/>`;});
  if(dual)svg+=`<path d="${GLYPHS.brace.path}" transform="translate(82 ${lower}) scale(.17 -${(lower-upper+72)/1000})" fill="#22352f"/><line x1="94" x2="94" y1="${upper-72}" y2="${lower}" stroke="#53685c" stroke-width="1.2"/>`;
  inds.forEach(i=>{const t=targets[i],col=(dual?Math.floor(i/2):i)%columns,used=Math.min(columns,groups-r*columns),x=used===1?600:270+col*(720/(used-1)),bottom=dual?(t.clef==='treble'?upper:lower):145,d=t.note.index-C.parse(t.clef==='treble'?'E4':'G2').index,y=bottom-d*9,done=q&&i<q.nextTarget,color=done?'#849a8f':i===active?'#27675f':'#22352f';svg+=`<g data-slot="${i}">`;if(i===active)svg+=`<circle cx="${x}" cy="${y}" r="25" fill="#dceee7"/>`;C.ledgerOffsets(d).forEach(k=>svg+=`<line x1="${x-21}" x2="${x+21}" y1="${bottom-k*9}" y2="${bottom-k*9}" stroke="${color}" stroke-width="1.7"/>`);svg+=`<ellipse data-note-index="${t.note.index}" data-clef="${t.clef}" cx="${x}" cy="${y}" rx="11.5" ry="8" transform="rotate(-20 ${x} ${y})" fill="${color}"/><line x1="${x+(d>=4?-10:10)}" x2="${x+(d>=4?-10:10)}" y1="${y}" y2="${y+(d>=4?63:-63)}" stroke="${color}" stroke-width="2.4"/><text x="${wide?x+34:x}" y="${wide?y+7:bottom+54}" text-anchor="${wide?'start':'middle'}" font-size="20" fill="${color}">${i+1}</text></g>`;});
  html+=svg+'</svg></div>';
 }
 return html;
}
function renderScore(){sizeScoreRows();$('stage').classList.toggle('dual',new Set(q.targets.map(t=>t.clef)).size>1);const top=$('stage').scrollTop;$('stage').innerHTML=score(q.targets,q.state==='answering'||q.state==='preparing'?q.nextTarget:-1);$('stage').scrollTop=top;const active=$('stage').querySelector(`[data-slot="${q.nextTarget}"]`)?.closest('.score-row');renderClassicHint();if(active){const t=active.offsetTop;if(t<$('stage').scrollTop||t+active.offsetHeight>$('stage').scrollTop+$('stage').clientHeight)$('stage').scrollTop=t;}}
function renderPreview(){if(session?.active)return;q=null;$('classicHint').hidden=true;if($('classicMemory'))$('classicMemory').hidden=true;$('practice').querySelector('.reading-board').classList.remove('has-memory');$('keyboardPrompt').textContent='点击琴键听音';$('practice').classList.remove('paused');updateHeader();$('progress').textContent=`每轮${db.settings.count}题`;$('timerText').textContent=C.totalLimit(db.settings)?`整题${C.totalLimit(db.settings)}秒`:'不限时';$('timerFill').style.width='100%';$('timerFill').classList.remove('urgent');$('timerText').classList.remove('urgent');$('pause').disabled=true;$('finish').hidden=true;$('next').hidden=true;$('feedbackCopy').textContent='';$('feedback').classList.remove('has-message');const targets=db.settings.mode==='dual'?[{clef:'treble',note:C.parse('E4')},{clef:'bass',note:C.parse('C3')}]:[{clef:db.settings.mode==='bass'?'bass':'treble',note:C.parse(db.settings.mode==='bass'?'C3':'E4')}];sizeScoreRows();$('stage').classList.toggle('dual',db.settings.mode==='dual');$('stage').innerHTML=score(targets)+`<div class="placeholder"><div class="content"><h3>准备好了吗？</h3><p>每题 ${db.settings.noteCount} 个音 · ${STRATEGIES[db.settings.strategy]}<br>点击「开始练习」，也可以先按键听音。</p></div></div>`;$('questionTitle').textContent='看谱，找到对应琴键';$('questionSub').textContent='中央C = C4 · 按谱面编号依次找琴键';$('targetSteps').hidden=true;renderKeyboard(true);}
function mistakeID(ts){return ts.map(C.profileKey).join('|');}
function markWrong(i){const s=q.slots[i];if(s.wrongRecorded)return;s.wrongRecorded=true;const t=q.targets[i],id=C.profileKey(t);let m=db.mistakes.find(m=>m.id===id);if(!m){m={id,targets:[t],errors:0,reviews:0,mastered:false};db.mistakes.push(m);}m.errors++;m.last=new Date().toISOString();m.mastered=false;db.mistakes=db.mistakes.slice(-200);save();}
function startRound(reviews=null){if(session?.active)return;if(window.PianoStudy?.beforeClassicStart?.(()=>startRound(reviews)))return;const settings=settingsFromUI();if(!settings)return;settings.input=window.PianoInput?.isMidi()?'midi':'touch';if(!reviews?.length&&!validatePractice(settings))return;db.settings=settings;save();const items=reviews?.length?C.shuffle(reviews).slice(0,settings.count):null;const actual={...settings,fullKeyboard:db.fullKeyboard,count:items?items.length:settings.count};if(items){const clefs=new Set(items.flatMap(m=>m.targets.map(t=>t.clef)));actual.mode=items.some(m=>new Set(m.targets.map(t=>t.clef)).size>1)?'dual':clefs.size>1?'mixed':[...clefs][0];actual.difficulty='extended';}session={active:true,settings:actual,generator:items?null:C.createGenerator(actual,()=>db.profiles),items,index:0,records:[],review:!!items};window.PianoInput?.apply(true);setPage('practice');lockSettings(true);closeDrawer();$('start').textContent='练习进行中';$('finish').hidden=false;renderKeyboard(true);nextQuestion();}
function nextQuestion(){cancelAnimationFrame(frame);const base=session.items?{id:session.index+1,targets:session.items[session.index].targets.map(t=>({...t,note:{...t.note}}))}:session.generator.next(session.index+1);const lim=C.totalLimit(session.settings,base.targets.length)*1000;$('classicHint').hidden=false;q={...base,slots:base.targets.map(()=>({reached:false,firstCorrect:null,firstMs:null,completionMs:null,completed:false,timeout:false,paused:false,committed:false,hint:false,hintLevel:0,hintDisplay:0,startElapsed:0})),state:'preparing',nextTarget:0,elapsed:0,limitMs:lim,remaining:lim,recordsDone:false};$('practice').classList.remove('paused');updateHeader();$('progress').textContent=`第 ${session.index+1} / ${session.settings.count} 题`;$('questionTitle').textContent=`依次找到 ${q.targets.length} 个音的琴键`;$('questionSub').textContent=session.settings.mode==='dual'?'按编号，同一列先上后下 · 上下谱表合计音数':'从左到右按编号 · 同一题共享总倒计时';$('feedbackCopy').textContent='';$('feedback').classList.remove('has-message');$('next').hidden=true;$('pause').disabled=false;setPauseLabel(false);$('keyboard').querySelectorAll('.key').forEach(k=>k.classList.remove('key-correct','key-wrong','pressed'));$('stage').scrollTop=0;renderScore();updateSteps();updateKeyPrompt();requestAnimationFrame(()=>{if(q.state!=='preparing')return;q.start=performance.now();q.deadline=q.start+q.remaining;q.state='answering';if(document.hidden||page!=='practice')pauseRound();else tick();});}
function elapsed(){return q.elapsed+(q.state==='answering'?performance.now()-q.start:0);}
function tick(){if(q?.state!=='answering')return;if(q.limitMs&&performance.now()>=q.deadline){settle('timeout');return;}renderTimer(q.limitMs?Math.max(0,q.deadline-performance.now()):0);frame=requestAnimationFrame(tick);}
function renderTimer(rem){const f=q.limitMs?rem/q.limitMs:1,urgent=q.limitMs&&rem<=3000;$('timerText').innerHTML=q.limitMs?`${(rem/1000).toFixed(1)}<small>秒</small>`:'不限时';$('timerFill').style.width=f*100+'%';$('timerFill').classList.toggle('urgent',!!urgent);$('timerText').classList.toggle('urgent',!!urgent);document.querySelector('.timer-track').setAttribute('aria-valuenow',String(Math.round(f*100)));}
function renderClassicHint(){
 const slot=q?.slots[q.nextTarget];let host=$('classicMemory');
 if(!host){host=document.createElement('div');host.id='classicMemory';host.className='memory-host classic-memory';$('stage').after(host);}
 $('practice').querySelector('.reading-board').classList.toggle('has-memory',!!slot?.hintDisplay);if(!slot||!session?.active){host.hidden=true;return;}
 const previous=q.nextTarget>0?q.targets[q.nextTarget-1]:null;
 PianoHints.render(host,{target:q.targets[q.nextTarget],previous,known:LearningCore.known(db.study.learning,q.targets[q.nextTarget].clef,session.settings.input),level:slot.hintDisplay||0,note:'本题已转为不限时学习；提示音单独统计，之后需无提示复习。',onLevel:setClassicHintLevel});
}
function setClassicHintLevel(level){
 if(q?.state!=='answering'||!session?.active)return;
 if(q.limitMs&&performance.now()>=q.deadline){settle('timeout');return;}
 const s=q.slots[q.nextTarget];if(!s)return;s.hintDisplay=level;
 if(level){s.hint=true;s.hintLevel=Math.max(s.hintLevel||0,level);q.usedHint=true;q.limitMs=0;q.remaining=0;renderTimer(0);}
 renderClassicHint();
}
function commit(i){const s=q.slots[i];if(s.committed||!s.reached)return;s.committed=true;C.observe(db.profiles,q.targets[i],s);StudyCore.observeNote(db.study,q.targets[i],{...s,task:'keyboard',input:session.settings.input||'touch'});save();}
function answer(midi,key=null,eventAt=performance.now(),source='touch'){if(q.state!=='answering')return;if(q.limitMs&&eventAt>=q.deadline){settle('timeout');return;}const i=q.nextTarget,s=q.slots[i],ms=Math.max(0,elapsed()-(performance.now()-eventAt)-s.startElapsed),correct=q.targets[i].note.midi===midi;s.reached=true;if(s.firstCorrect===null){s.firstCorrect=correct;s.firstMs=ms;s.firstMidi=midi;s.context=C.trialContext({...session.settings,input:source},db.fullKeyboard);}if(!correct){markWrong(i);if(key){key.classList.add('key-wrong');setTimeout(()=>key.classList.remove('key-wrong'),350);}$('feedback').classList.add('has-message');$('feedbackCopy').className='feedback-copy bad';$('feedbackCopy').textContent=source==='midi'?MidiCore.feedback(q.targets[i].note.midi,midi):`第 ${i+1} 个音还没找对，再看谱号和位置。`;return;}s.completed=true;s.completionMs=ms;commit(i);if(key){key.classList.add('key-correct');setTimeout(()=>key.classList.remove('key-correct'),250);}q.nextTarget++;updateSteps();if(q.nextTarget===q.targets.length)settle('correct');else{q.slots[q.nextTarget].startElapsed=elapsed();renderScore();updateKeyPrompt();$('feedback').classList.add('has-message');$('feedbackCopy').className='feedback-copy good';$('feedbackCopy').textContent=`第 ${i+1} 个已完成，继续第 ${i+2} 个。`;}}
function updateSteps(){$('targetSteps').hidden=false;$('targetSteps').innerHTML=q.targets.map((t,i)=>`<span class="target-step ${i<q.nextTarget?'done':i===q.nextTarget?'active':''}" aria-label="第${i+1}个音${i<q.nextTarget?'已完成':i===q.nextTarget?'当前音':'未作答'}">${i<q.nextTarget?'✓':i+1}</span>`).join('');}
function updateKeyPrompt(){$('keyboardPrompt').textContent=window.PianoInput?.isMidi()?'在实体琴上弹出目标音':'点击琴键作答';$('questionSub').textContent=q.nextTarget<q.targets.length?`当前第 ${q.nextTarget+1} 个 · ${q.targets[q.nextTarget].clef==='treble'?'高音谱表':'低音谱表'}`:'本题已完成 · 可以按键听音';}
function record(status){if(q.recordsDone)return;q.recordsDone=true;session.records.push({targets:q.targets.map(t=>({...t,note:{...t.note}})),slots:q.slots.map(s=>({...s})),status,elapsed:q.elapsed});}
function settle(kind){if(q.state!=='answering'||q.recordsDone)return;q.elapsed=elapsed();cancelAnimationFrame(frame);if(kind==='timeout'){const s=q.slots[q.nextTarget];s.context=s.context||C.trialContext(session.settings,db.fullKeyboard);s.reached=true;s.timeout=true;s.completionMs=q.elapsed-s.startElapsed;if(s.firstCorrect===null)s.firstCorrect=false;markWrong(q.nextTarget);commit(q.nextTarget);}const wrong=q.slots.some(s=>s.reached&&s.firstMs!==null&&!s.firstCorrect),status=kind==='correct'?(q.slots.some(s=>s.hint)?'assisted':wrong?'corrected':'firstCorrect'):(wrong?'wrongTimeout':'noAnswerTimeout');q.state=kind;record(status);if(session.review&&kind==='correct'){const m=db.mistakes.find(m=>m.id===mistakeID(q.targets));if(m){m.reviews=(m.reviews||0)+1;save();}}$('classicHint').hidden=true;if($('classicMemory'))$('classicMemory').hidden=true;$('pause').disabled=true;$('feedback').classList.add('has-message');$('feedbackCopy').className='feedback-copy '+(kind==='correct'?'good':'bad');$('feedbackCopy').innerHTML=`<strong>${kind==='correct'?'本题完成':'时间到'}</strong> · 已完成 ${q.nextTarget}/${q.targets.length} 个音${kind==='timeout'?`；第 ${q.nextTarget+1} 个待加强，后续音未作答。`:''}<details><summary>查看音高与位置</summary>${q.targets.map((t,i)=>`${i+1}. ${esc(describe([t]))} · ${esc(C.location(t.clef,t.note))}`).join('<br>')}</details>`;$('next').hidden=false;$('next').textContent=session.index===session.settings.count-1?'查看结果':'下一题';$('keyboardPrompt').textContent='已揭晓 · 可以按键听音';$('questionSub').textContent=kind==='correct'?'本题已完成 · 可以按键听音':`已完成 ${q.nextTarget}/${q.targets.length} 个 · 展开下方查看答案`;renderScore();if(kind==='timeout')renderTimer(0);}
function pauseRound(reason='点击继续恢复答题。'){if(!session?.active||q?.state!=='answering')return;if(q.limitMs&&performance.now()>=q.deadline){settle('timeout');return;}q.elapsed=elapsed();q.remaining=q.limitMs?Math.max(0,q.deadline-performance.now()):0;q.slots[q.nextTarget].paused=true;q.state='paused';cancelAnimationFrame(frame);$('practice').classList.add('paused');$('stage').insertAdjacentHTML('beforeend',`<div class="placeholder" id="pauseCover"><div class="content"><h3>练习已暂停</h3><p>${esc(reason)}</p></div></div>`);setPauseLabel(true);renderTimer(q.remaining);$('timerText').textContent='已暂停';}
function resumeRound(){if(q?.state!=='paused'||page!=='practice'||document.hidden)return;$('pauseCover')?.remove();$('practice').classList.remove('paused');q.start=performance.now();q.deadline=q.start+q.remaining;q.state='answering';setPauseLabel(false);tick();}
function moveNext(){if(!session?.active||!q?.recordsDone)return;if(session.index===session.settings.count-1){endRound(true);return;}session.index++;nextQuestion();}
function endRound(complete=false){if(!session?.active)return;cancelAnimationFrame(frame);if(q&&!q.recordsDone){q.elapsed=elapsed();q.slots.forEach((s,i)=>{if(s.reached&&!s.committed){s.completionMs=q.elapsed-s.startElapsed;commit(i);}});if(q.slots.some(s=>s.reached))record('stopped');}session.active=false;if(q)q.state='finished';lockSettings(false);strategyHints();$('start').textContent='开始练习';lastReport=C.report(session.records,session.settings,complete);lastReport.review=session.review;if(lastReport.total){db.reports.push(lastReport);db.reports=db.reports.slice(-30);save();}setPage('result');renderResult(lastReport);}
function setPage(name){window.PianoEar?.beforeNavigate?.(name);window.PianoSongs?.beforeNavigate?.(name);window.PianoFoundation?.beforeNavigate?.(name);window.PianoStudy?.beforeNavigate?.(name);if(name!=='practice'&&session?.active&&q?.state==='answering')pauseRound('返回练习后点击继续。');page=name;['practice','mistakes','profiles','history','help','notePicker','result','today','topics','reading','progressPage','studyLesson','rhythmPage','foundationPage','songsPage','earPage'].forEach(p=>$(p).hidden=p!==name);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));if(name==='mistakes')renderMistakes();if(name==='profiles')renderProfiles();if(name==='history')renderHistory();if(name==='help')renderHelp();if(name==='notePicker'){closeDrawer();renderNotePicker();}if(name==='practice'&&!session?.active)renderPreview();updateHeader();$('openSettings').hidden=name!=='practice';window.PianoStudy?.navigate?.(name);window.PianoRhythm?.navigate?.(name);window.PianoFoundation?.navigate?.(name);window.PianoSongs?.navigate?.(name);window.PianoEar?.navigate?.(name);window.PianoInput?.sync();}
function pct(n){return Number.isFinite(n)?Math.round(n*100)+'%':'暂无';}
function date(s){const d=new Date(s);return Number.isNaN(d.getTime())?'日期未知':d.toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function describe(ts){return ts.map(t=>`${t.clef==='treble'?'高音':'低音'} ${C.label(t.note)}`).join(' / ');}
function renderResult(r){const legacy=r.version!==3;$('result').innerHTML=`<div class="page-head"><div><h2>${r.complete?'本轮练习完成':'本轮提前结束'}</h2><p>${esc(MODE_TITLES[r.settings.mode]||'识谱')} · ${esc(STRATEGIES[r.settings.strategy]||'旧版练习')} · ${r.total} 题${legacy?' · 旧版记录（整题统计）':''}</p></div><button id="again" class="primary" ${session?.active?'disabled':''}>再练一轮</button></div><div class="stats"><div><div class="stat-label">${legacy?'整题':'无提示逐音'}首次准确率</div><div class="stat-value">${pct(legacy?r.accuracy:r.noteAccuracy)}</div><div class="stat-help">${legacy?'旧版统计口径':`${r.correctNotes} / ${r.unaidedNotes??r.seenNotes} 个无提示音 · ${r.assistedNotes||0} 个提示音`}</div></div><div><div class="stat-label">${legacy?'整题完成率':'已完成音符'}</div><div class="stat-value">${legacy?pct(r.completion):r.completedNotes}</div><div class="stat-help">${legacy?'包括改正后完成':`${r.unseenNotes} 个后续音未作答，不计错`}</div></div><div><div class="stat-label">${legacy?'整题':'逐音'}正确找键用时</div><div class="stat-value">${r.medianMs==null?'暂无':(r.medianMs/1000).toFixed(1)+'<span> 秒</span>'}</div><div class="stat-help">中位数 · ${r.speedSamples||0} 个样本</div></div></div><div class="result-summary">整题首次准确率 ${pct(r.accuracy)} · 整题完成率 ${pct(r.completion)}<br>无提示首次正确才计入识别速度；提示与暂停样本排除。提前结束的题不计入整题完成率。</div><div class="table-wrap"><table><thead><tr><th>谱表</th><th>无提示音数</th><th>首次正确</th><th>准确率</th></tr></thead><tbody>${['treble','bass'].map(c=>`<tr><td>${c==='treble'?'高音谱表':'低音谱表'}</td><td>${r.per[c].seen}</td><td>${r.per[c].correct}</td><td>${r.per[c].seen?pct(r.per[c].correct/r.per[c].seen):'未练习'}</td></tr>`).join('')}</tbody></table></div><div class="section"><h3>逐题明细</h3>${r.records.map((a,i)=>`<details class="record-detail"><summary>第 ${i+1} 题 · ${{firstCorrect:'首次全部正确',assisted:'提示辅助完成',corrected:'改正后完成',wrongTimeout:'超时',noAnswerTimeout:'超时',stopped:'提前结束'}[a.status]||'已结束'}</summary><table><thead><tr><th>音符</th><th>结果</th><th>首次用时</th></tr></thead><tbody>${a.targets.map((t,j)=>{const s=a.slots?.[j];return `<tr><td>${j+1}. ${esc(describe([t]))}</td><td>${legacy?(a.firstMatch?.[j]?'首次正确':'未首次正确'):!s.reached?'未作答':s.timeout?'超时':s.completed?s.firstCorrect?'首次正确':'改正完成':'中断'}${s?.hint?' · '+PianoHints.label(s.hintLevel):''}${s?.paused?' · 暂停过':''}</td><td>${s?.firstMs!=null&&!s.hint?(s.firstMs/1000).toFixed(1)+'秒':legacy?(a.firstMs/1000).toFixed(1)+'秒／整题':'—'}</td></tr>`;}).join('')}</tbody></table></details>`).join('')}</div>`;$('again').onclick=()=>{db.settings=validSettings(r.settings);applySettings();startRound();};}
function renderMistakes(){const pending=db.mistakes.filter(m=>!m.mastered);$('mistakes').innerHTML=`<div class="page-head"><div><h2>错题本</h2><p>待复习 ${pending.length} 项 · 新版按具体音高单独记录。</p></div><div class="actions"><button id="reviewAll" class="primary" ${!pending.length||session?.active?'disabled':''}>开始复习</button><button id="clearMistakes" ${!db.mistakes.length?'disabled':''}>清空错题</button></div></div>${db.mistakes.length?`<div class="table-wrap"><table><thead><tr><th>音高</th><th>错误次数</th><th>复习正确</th><th>操作</th></tr></thead><tbody>${[...db.mistakes].reverse().map(m=>`<tr><td>${esc(describe(m.targets))}${m.mastered?' · 已掌握':''}</td><td>${m.errors}</td><td>${m.reviews||0}</td><td><button data-master="${esc(m.id)}">${m.mastered?'重新复习':'标记掌握'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>暂时没有错题</h3><p>选错或当前音超时会保存在这里。</p></div>'}`;$('reviewAll').onclick=()=>startRound(pending);$('clearMistakes').onclick=()=>confirmAction('清空错题？','个人音符档案和练习记录会保留。',()=>{db.mistakes=[];save();renderMistakes();});$('mistakes').querySelectorAll('[data-master]').forEach(b=>b.onclick=()=>{const m=db.mistakes.find(m=>m.id===b.dataset.master);m.mastered=!m.mastered;save();renderMistakes();});}
function renderProfiles(){const bases={treble:C.baseline(db.profiles,'treble'),bass:C.baseline(db.profiles,'bass')};const rows=Object.values(db.profiles).map(p=>({...p,w:C.weakness(p,C.baseline(db.profiles,p.target.clef,p.samples.at(-1)?.context),p.samples.at(-1)?.context)})).sort((a,b)=>b.w.score-a.w.score||a.target.note.index-b.target.note.index);$('profiles').innerHTML=`<div class="page-head"><div><h2>你的薄弱音</h2><p>高音、低音及八度分别记录，慢音按音域、单音或多音及键盘范围分开判断。做错的音、首次答对但用时较长的音会增加练习。</p></div><div class="actions"><button id="practiceWeak" class="primary" ${session?.active||!rows.some(p=>p.w.score>0)?'disabled':''}>只练薄弱音</button><button id="exportData">导出数据</button><button id="importData" ${session?.active||window.PianoStudy?.isActive?.()?'disabled':''}>导入数据</button><button id="resetProfiles" ${!rows.length||session?.active?'disabled':''}>重置音符档案</button></div></div><p class="result-summary">针对性练习按每次抽样约60%选择薄弱音，30%覆盖音域，10%随机探索；没有符合条件的薄弱音时回到均衡覆盖。避免同谱表连续相同音，因此实际比例会变化。<br>慢音至少需要3次首次正确、未暂停样本；近期中位数高于同谱表同条件个人基准的1.5倍且超过2秒才加练。连续5次首次正确会解除易错标记。</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>音高</th><th>练习次数</th><th>累计首次准确率</th><th>近期正确用时</th><th>当前状态</th><th>专项练习</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(describe([p.target]))}</td><td>${p.seen}</td><td>${pct((p.seen-p.errors)/p.seen)}</td><td>${p.w.time==null?'暂无':(p.w.time/1000).toFixed(1)+'秒'}</td><td>${p.w.error?(p.samples.length<3?'错音待观察 ':'容易错 '):''}${p.w.slow?'找键较慢':p.w.error?'':p.samples.length<3?'继续积累样本':'已稳定'}</td><td><button data-practice-note="${esc(C.profileKey(p.target))}" ${session?.active?'disabled':''}>练这个音</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>先做一轮练习</h3><p>每个已轮到的音会建立档案，下一题开始采用更新后的记录。</p></div>'}<input id="dataFile" type="file" accept=".json,application/json" hidden>`;$('practiceWeak').onclick=()=>configureWeak(rows.filter(p=>p.w.score>0).map(p=>p.target));$('profiles').querySelectorAll('[data-practice-note]').forEach(b=>b.onclick=()=>configureSelected([b.dataset.practiceNote]));$('resetProfiles').onclick=()=>confirmAction('重置音符档案？','针对性出题将重新积累数据，错题本和历史报告保留。',()=>{db.profiles={};save();renderProfiles();});$('exportData').onclick=()=>{if(window.PianoAndroid){window.PianoAndroid.exportData('识谱练习数据_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(db,null,2));return;}const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='识谱练习数据_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('importData').onclick=()=>window.PianoAndroid?window.PianoAndroid.importData():$('dataFile').click();$('dataFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('文件太大');const imported=normalize(JSON.parse(await file.text()));confirmAction('导入练习数据？','导入将替换本页的设置、音符档案、错题与历史。建议先导出当前数据。',()=>{db=imported;save();applySettings();renderProfiles();});}catch(e){showStorage('导入失败：请使用本应用导出的、5MB以内的数据JSON文件。');}};}
function renderHistory(){$('history').innerHTML=`<div class="page-head"><div><h2>练习记录</h2><p>保留最近30轮，旧版报告继续可查。</p></div><button id="clearHistory" ${db.reports.length?'':'disabled'}>清空记录</button></div>${db.reports.length?`<div class="table-wrap"><table><thead><tr><th>时间／模式</th><th>题量</th><th>首次准确率</th><th>正确找键中位数</th><th></th></tr></thead><tbody>${[...db.reports].reverse().map(r=>`<tr><td>${esc(date(r.date))}<br>${esc(MODE_TITLES[r.settings.mode]||'识谱')}</td><td>${r.total}</td><td>${pct(r.version===3?r.noteAccuracy:r.accuracy)}<br><small>${r.version===3?'逐音':'旧版整题'}</small></td><td>${r.medianMs==null?'暂无':(r.medianMs/1000).toFixed(1)+'秒'}</td><td><button data-report="${esc(r.id)}">查看</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>还没有练习记录</h3></div>'}`;$('clearHistory').onclick=()=>confirmAction('清空记录？','个人音符档案和错题本会保留。',()=>{db.reports=[];save();renderHistory();});$('history').querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{setPage('result');renderResult(db.reports.find(r=>r.id===b.dataset.report));});}
 function renderKeyboard(center=false){const settings=session?.active?session.settings:db.settings,[lo,hi]=C.keyboardRange(settings,db.fullKeyboard),isBlack=m=>[1,3,6,8,10].includes(m%12),whiteCount=Array.from({length:hi-lo+1},(_,i)=>lo+i).filter(m=>!isBlack(m)).length;let whites='',blacks='',w=0;for(let m=lo;m<=hi;m++){const name=C.midiName(m);if(isBlack(m)){blacks+=`<button class="key black" data-midi="${m}" aria-label="${name}，黑键" style="left:${w/whiteCount*100}%;width:${.62/whiteCount*100}%"></button>`;}else{whites+=`<button class="key white" data-midi="${m}" aria-label="${name}，白键">${m%12===0?`<span class="c-label">${name}</span>`:''}</button>`;w++;}}$('keyboard').style.width='100%';$('keyboard').style.minWidth=whiteCount*44+'px';$('keyboard').innerHTML=whites+blacks;$('localKeys').classList.toggle('selected',!db.fullKeyboard);$('fullKeys').classList.toggle('selected',db.fullKeyboard);$('localKeys').setAttribute('aria-pressed',String(!db.fullKeyboard));$('fullKeys').setAttribute('aria-pressed',String(db.fullKeyboard));$('sound').textContent=`声音：${db.sound?'开':'关'}`;$('sound').setAttribute('aria-pressed',String(db.sound));$('keyRange').textContent=`${C.midiName(lo)}—${C.midiName(hi)} · ${db.fullKeyboard?'88键':'局部键盘'} · 可横向滚动`;
  if(center)requestAnimationFrame(()=>{const mid=$('keyboard').querySelector('[data-midi="60"]')||$('keyboard').querySelector('.white');const scroll=$('keyboardScroll');scroll.scrollLeft=Math.max(0,mid.offsetLeft-scroll.clientWidth/2);});
 }
 function play(midi){if(!db.sound)return;try{const voice=window.PianoAudio.note(midi,{duration:.65,volume:.5});voice.ready.then(ok=>{if(!ok&&window.PianoAudio.status().error)showStorage('钢琴音色未能播放，请重新打开应用后重试。');});}catch(e){showStorage('声音未能启用，请检查设备声音设置；识谱练习仍可继续。');}}
 function keyPress(midi,key){if(window.PianoInput&&!window.PianoInput.touchAllowed())return;if(q?.state==='paused'||modalCallback)return;play(midi);key.classList.add('pressed');setTimeout(()=>key.classList.remove('pressed'),180);if(q?.state==='answering'&&page==='practice')answer(midi,key);}
 function confirmAction(title,text,callback){modalRestoreFocus=document.activeElement;modalCallback=callback;$('modalConfirm').onclick=()=>closeModal(true);$('modalCancel').onclick=()=>closeModal(false);$('modalConfirm').textContent='确定';$('modalCancel').textContent='取消';$('modalTitle').textContent=title;$('modalText').textContent=text;$('modalLayer').hidden=false;$('modalCancel').focus();}
 function closeModal(confirmed){const callback=modalCallback,cleanup=modalCleanup;modalCallback=null;modalCleanup=null;cleanup?.();$('modalLayer').hidden=true;modalRestoreFocus?.focus();if(confirmed)callback?.();}
 function staffMarkup(target,bottom,x=400,color='#22352f',highlight=false){const space=18,ref=C.parse(target.clef==='treble'?'E4':'G2').index,d=target.note.index-ref,y=bottom-d*space/2,clefY=bottom-(target.clef==='treble'?space:space*3);let s='';for(let i=0;i<5;i++)s+=`<line x1="95" x2="700" y1="${bottom-i*space}" y2="${bottom-i*space}" stroke="#32433b" stroke-width="1.35"/>`;s+=`<path d="${GLYPHS[target.clef].path}" transform="translate(104 ${clefY}) scale(${space/250} -${space/250})" fill="#22352f"/>`;C.ledgerOffsets(d).forEach(k=>s+=`<line data-ledger="${k}" x1="${x-21}" x2="${x+21}" y1="${bottom-k*space/2}" y2="${bottom-k*space/2}" stroke="${color}" stroke-width="1.7"/>`);if(highlight)s+=`<circle cx="${x}" cy="${y}" r="23" fill="#dceee3"/>`;s+=`<ellipse data-note-index="${target.note.index}" data-clef="${target.clef}" cx="${x}" cy="${y}" rx="11.5" ry="8" transform="rotate(-20 ${x} ${y})" fill="${color}"/>`;const down=d>=4;const stemX=x+(down?-10:10);s+=`<line x1="${stemX}" x2="${stemX}" y1="${y}" y2="${y+(down?63:-63)}" stroke="${color}" stroke-width="2.4" stroke-linecap="round"/>`;return s;}
 function notation(targets,{highlight=-1,teaching=false}={}){const dual=targets.length===2,height=dual?400:280;let s=`<svg viewBox="0 0 760 ${height}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${dual?'高音与低音双谱表':'五线谱识谱题'}">`;targets.forEach((t,i)=>{s+=staffMarkup(t,dual?(i?320:150):180,420,highlight===i?'#27675f':'#22352f',highlight===i);if(dual)s+=`<text x="59" y="${i?283:113}" fill="#718079" font-size="14" text-anchor="middle">${i?'下':'上'}</text>`;});if(dual){s+='<line x1="90" x2="90" y1="78" y2="320" stroke="#32433b" stroke-width="1.7"/>';const b=GLYPHS.brace;s+=`<path d="${b.path}" transform="translate(72 320) scale(.19 -.242)" fill="#32433b"/>`;}return s+'</svg>';}
 function helpStaff(c){const notes=c==='treble'?['E4','G4','B4','D5','F5']:['G2','B2','D3','F3','A3'];let s='<svg viewBox="0 0 760 280" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="五条线的参照音">';s+=staffMarkup({clef:c,note:C.parse(notes[0])},180,230);for(let i=1;i<5;i++){const n=C.parse(notes[i]),x=230+i*95,y=180-i*18;s+=`<ellipse cx="${x}" cy="${y}" rx="11" ry="8" transform="rotate(-20 ${x} ${y})" fill="#22352f"/>`;}notes.forEach((n,i)=>s+=`<text x="${230+i*95}" y="230" text-anchor="middle" fill="#27675f" font-size="21">${n}</text>`);return s+'</svg>';}
 function renderHelp(){$('help').innerHTML=`<div class="page-head"><div><h2>学习说明</h2><p>看谱 → 找到具体琴键 → 按下听音。先认准，再提速。</p></div></div><div class="help-grid"><div class="help-panel"><h3>高音谱表</h3><p>五条线自下而上：E4、G4、B4、D5、F5。</p>${helpStaff('treble')}<p>G4位于第二线。中央C（C4）位于下加一线。</p></div><div class="help-panel"><h3>低音谱表</h3><p>五条线自下而上：G2、B2、D3、F3、A3。</p>${helpStaff('bass')}<p>F3位于第四线。中央C（C4）位于上加一线。</p></div></div><div class="section"><h3>自然音与固定唱名</h3><div class="note-map">${C.LETTERS.map((n,i)=>`<span>${n} · ${C.SOLFEGE[i]}</span>`).join('')}</div><p class="helptext muted" style="margin-top:12px">本页采用固定唱名与科学音高记号，中央C记作C4。C3、C4、C5是不同八度的同名音，必须按到谱面对应的具体琴键。</p></div><div class="section helptext"><h3>怎样找琴键</h3><ol><li>黑键按两枚、三枚分组。两枚黑键左侧紧邻的白键是C。</li><li>每个C键底部标注音区，C4额外标注中央C。其余琴键不标答案，帮助形成真实键盘位置记忆。</li><li>局部键盘的范围由练习模式和难度确定，不随每道题移动。超出屏幕时可以横向滚动，或使用向左、向右按钮。</li><li>88键模式显示A0到C8的全部琴键。黑白键都可按下发声，本版题目只考自然音。</li><li>鼠标、触屏均可按键；也可用Tab聚焦琴键，再按Enter或空格。声音按钮可关闭音效。</li></ol></div><div class="section helptext"><h3>自己选音与薄弱音专项</h3><p>在出题方式中选「自己选音」，再点「选择练习音」，勾选当前模式和音域中的具体音高。混合与双谱表需要高、低谱表各至少一个音。同一谱表只选一个音时可以连续重复。</p><p>「薄弱音专项」只练开始本轮时已判定的易错音和慢音；本轮范围固定，下轮重新评估。薄弱音页面也可直接选择「练这个音」。专项模式没有合适音符时会提示，不会补入其他音。</p></div><div class="section helptext"><h3>怎样练双谱表</h3><p>按谱面编号，每一列先上方高音，再下方低音，随后进入下一列。尚未认完全部音时，计时仍继续。同一列先上方再下方，按编号完成全部音。左右手提示帮助理解常见钢琴读谱场景，谱号才决定音高。</p></div><div class="section helptext"><h3>计时和统计</h3><ol><li>选错可在剩余时间内改正，错题自动记录。改正完成不会计成首次正确。</li><li>整题全部音认对后停止计时并揭晓答案，点击下一题继续。超时显示正确音高和位置。</li><li>主动暂停或切换页面会遮住题目；回来后点击继续。暂停时所在的音不计入识别速度，其他已完成音仍保留。</li><li>识别用时取首次正确且该音未暂停的逐音用时中位数。新版逐音计时，从轮到该音开始，到第一次按键为止。</li><li>开始时可选不限时。连续几轮首次准确率稳定后，再尝试缩短时限。</li></ol></div><div class="section helptext"><h3>离线使用与声音</h3><p>安装后可直接离线练习。钢琴试听、课程示范与曲谱播放使用随应用内置的 Salamander 钢琴采样，离线播放；节拍器与节奏提示使用本地短音。所有谱号路径均内置，无需联网。采样：Salamander Grand Piano，作者 Alexander Holm，Yamaha C5；采用 CC BY 3.0，来源 Tonejs/audio。采样文件保持原样，播放时应用变调、音量与松键衰减。许可：https://creativecommons.org/licenses/by/3.0/；来源：https://github.com/Tonejs/audio/tree/efd8296360f9526e379bfbe5c1698ff54d6a1d34/salamander。设置、错题和最近报告保存在应用内；卸载应用或清除应用数据会删除记录。可在薄弱音页面导出JSON备份，也可导入旧网页版导出的数据。若浏览器不允许保存，会明确提示并继续提供练习。</p></div><div class="section helptext"><h3>关于节奏</h3><p>自由识谱的倒计时用于找键速度。节奏与拍子课程按完整小节进行，支持稳拍、八分细分、时值与休止、节奏型、听后模仿和双侧配合。时值模式用按住表示延续，松开表示结束；它不作为连奏、断奏的通用判定。</p></div>`;}
let drawerFocus=null;
function updateHeader(){const settings=session?.active?session.settings:db.settings;$('modeTitle').textContent=(session?.review&&session.active?'错题复习':MODE_TITLES[settings.mode].replace('识谱',''))+' · '+STRATEGIES[settings.strategy];}
function openDrawer(){if(q?.state==='answering')pauseRound('设置已打开，关闭后点击继续。');drawerFocus=document.activeElement;$('sidebar').hidden=false;$('settingsBackdrop').hidden=false;$('settingsToggle').textContent='关闭';$('settingsToggle').focus({preventScroll:true});}
function closeDrawer(){$('sidebar').hidden=true;$('settingsBackdrop').hidden=true;$('sidebar').classList.remove('open');drawerFocus?.focus?.({preventScroll:true});}
function setPauseLabel(resume){$('pause').innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${resume?'m8 4 12 8-12 8Z':'M8 5v14M16 5v14'}"/></svg><span>${resume?'继续':'暂停'}</span>`;}
function sizeScoreRows(){const h=$('stage').clientHeight;if(h>0)$('stage').style.setProperty('--score-row-height',h+'px');}
window.importPianoData=raw=>{if(session?.active||window.PianoStudy?.isActive?.()){showStorage('请先结束当前训练，再导入数据。');return;}try{if(typeof raw!=='string'||raw.length>5e6)throw Error('文件过大');const imported=normalize(JSON.parse(raw));confirmAction('导入练习数据？','导入会替换当前设置、音符档案、错题与历史。建议先导出备份。',()=>{db=imported;save();applySettings();setPage('profiles');});}catch(e){showStorage('导入失败：请使用本应用或旧网页版导出的5MB以内JSON数据。');}};
window.PianoPause=()=>{window.PianoEar?.pause?.();window.PianoStudy?.pause?.();pauseRound('应用已切换到后台，回来后点击继续。');window.PianoAudio.silence();};
window.PianoBack=()=>{if(window.PianoEar?.back?.())return true;if(window.PianoFoundation?.back?.())return true;if(window.PianoStudy?.back?.())return true;if(modalCallback){closeModal(false);return true;}if(!$('sidebar').hidden){closeDrawer();return true;}if(page!=='practice'&&page!=='today'){setPage('today');return true;}if(session?.active){if(q?.state==='answering')pauseRound();confirmAction('结束本轮？','已作答音的统计会保留，未轮到的音不会计错。',()=>endRound(false));return true;}return false;};
window.addEventListener('resize',()=>{sizeScoreRows();if(session?.active&&q){if(q.state==='paused'){const content=$('pauseCover')?.outerHTML;$('stage').innerHTML=score(q.targets,-1)+(content||'');}else renderScore();}else if(page==='practice')renderPreview();});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&!$('sidebar').hidden&&!modalCallback){const list=[...$('sidebar').querySelectorAll('button:not(:disabled),select:not(:disabled),input:not(:disabled)')].filter(el=>!el.hidden&&el.offsetParent!==null),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Escape'&&!$('sidebar').hidden){e.preventDefault();e.stopImmediatePropagation();closeDrawer();}});
load();applySettings();renderPreview();
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(session?.active)return;db.settings.mode=b.dataset.mode;if(b.dataset.mode==='dual'&&Number($('noteCount').value)<2)db.settings.noteCount=2;applySettings();updateSettings();});
['difficulty','count','strategy','timing','secondsPerNote'].forEach(id=>$(id).onchange=updateSettings);['noteCount','customLimit'].forEach(id=>$(id).oninput=updateSettings);
$('chooseNotes').onclick=()=>{if(!session?.active)setPage('notePicker');};$('start').onclick=()=>startRound();$('launch').onclick=()=>startRound();$('pause').onclick=()=>q?.state==='paused'?resumeRound():pauseRound();$('next').onclick=moveNext;
$('classicHint').onclick=()=>setClassicHintLevel(Math.min(3,(q?.slots[q.nextTarget]?.hintDisplay||0)+1));
$('finish').onclick=()=>{if(q?.state==='answering')pauseRound();confirmAction('结束本轮？','已作答的音会保留统计；尚未轮到的音不会计错。',()=>endRound(false));};
$('settingsToggle').onclick=closeDrawer;$('openSettings').onclick=openDrawer;$('settingsBackdrop').onclick=closeDrawer;['noteMinus','notePlus'].forEach(id=>$(id).onclick=()=>{if(session?.active)return;const minimum=db.settings.mode==='dual'?2:1;$('noteCount').value=Math.max(minimum,Math.min(15,(Number($('noteCount').value)||minimum)+(id==='notePlus'?1:-1)));updateSettings();});
$('localKeys').onclick=()=>{db.fullKeyboard=false;if(session?.active)session.settings.fullKeyboard=false;save();renderKeyboard(true);};$('fullKeys').onclick=()=>{db.fullKeyboard=true;if(session?.active)session.settings.fullKeyboard=true;save();renderKeyboard(true);};$('sound').onclick=()=>{db.sound=!db.sound;save();$('sound').textContent=`声音：${db.sound?'开':'关'}`;$('sound').setAttribute('aria-pressed',String(db.sound));};
let touchKey=null;
$('keyboard').addEventListener('pointerdown',e=>{const k=e.target.closest('[data-midi]');if(!k||e.button>0)return;if(e.pointerType==='touch'){touchKey={key:k,id:e.pointerId,x:e.clientX,y:e.clientY};return;}e.preventDefault();k.focus({preventScroll:true});keyPress(Number(k.dataset.midi),k);});
$('keyboard').addEventListener('pointerup',e=>{if(!touchKey||touchKey.id!==e.pointerId)return;const t=touchKey;touchKey=null;if(Math.hypot(e.clientX-t.x,e.clientY-t.y)>10)return;e.preventDefault();t.key.focus({preventScroll:true});keyPress(Number(t.key.dataset.midi),t.key);});
$('keyboard').addEventListener('pointercancel',()=>{touchKey=null;});$('keyboard').addEventListener('click',e=>{const k=e.target.closest('[data-midi]');if(k&&e.detail===0)keyPress(Number(k.dataset.midi),k);});
$('keysLeft').onclick=()=>$('keyboardScroll').scrollBy({left:-$('keyboardScroll').clientWidth*.65,behavior:'smooth'});$('keysRight').onclick=()=>$('keyboardScroll').scrollBy({left:$('keyboardScroll').clientWidth*.65,behavior:'smooth'});
$('modalCancel').onclick=()=>closeModal(false);$('modalConfirm').onclick=()=>closeModal(true);
document.addEventListener('visibilitychange',()=>{if(document.hidden){window.PianoStudy?.pause?.();pauseRound('页面已离开，回来后点击继续。');}});
document.addEventListener('keydown',e=>{if(modalCallback){if(e.key==='Escape'){e.preventDefault();closeModal(false);}if(e.key==='Tab'){const b=[$('modalCancel'),$('modalConfirm')],i=b.indexOf(document.activeElement);e.preventDefault();b[(i+(e.shiftKey?-1:1)+2)%2].focus();}return;}if(e.repeat||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'&&page==='practice'&&session?.active){e.preventDefault();q.state==='paused'?resumeRound():pauseRound();}});
window.PianoHost={showClassicReport:r=>{setPage('result');renderResult(r);},getDB:()=>db,closeModal,setModalCleanup:fn=>{modalCleanup=fn;},save,showPage:setPage,play,confirm:confirmAction,notice:showStorage,glyphs:GLYPHS,classicActive:()=>!!session?.active,modalOpen:()=>!!modalCallback,configureClassic:(settings)=>{if(session?.active){setPage('practice');return;}db.settings=validSettings({...db.settings,...settings});applySettings();save();setPage('practice');},inputSource:()=>session?.settings.input||'touch',pauseClassic:pauseRound,stopForInputChange:()=>endRound(false),
  midiEvent:e=>{if(page!=='practice'||!session?.active||modalCallback)return;if(e.type==='on'&&q?.state==='answering')answer(e.note,null,e.at,'midi');},
  midiReady:()=>page==='practice'&&session?.active&&q?.state==='correct'&&!modalCallback,
  midiToken:()=>q,
  midiAdvance:()=>{if(page==='practice'&&q?.state==='correct')moveNext();},
  startClassic:()=>startRound()};
})();
